   346|function resolveSendBranch(
   347|  deliveryBranch: DeliveryBranchStatus['branch'],
   348|  runtimeSource: RuntimeDebugSnapshot['source'],
   349|  httpStatus: string,
   350|): SendBranchProofRow {
   351|  if (deliveryBranch === 'not_observed') {
   352|    return { branch: null, label: 'pending', context: 'no send observed' };
   353|  }
   354|
   355|  const statusFragment = httpStatus !== 'pending' && httpStatus !== 'none' ? ` · ${httpStatus}` : '';
   356|
   357|  if (deliveryBranch === 'remote_db_insert') {
   358|    if (runtimeSource === 'remote_api' || runtimeSource === 'local_app_brain') {
   359|      return { branch: 'primary_realtime', label: 'primary_realtime', context: `assistant db insert${statusFragment}` };
   360|    }
   361|    if (runtimeSource === 'provider_fallback') {
   362|      return { branch: 'alternate_shared', label: 'alternate_shared', context: `gateway db insert${statusFragment}` };
   363|    }
   364|    return { branch: 'primary_realtime', label: 'primary_realtime', context: `db insert · source ${runtimeSource}${statusFragment}` };
   365|  }
   366|
   367|  if (deliveryBranch === 'local_fallback') {
   368|    return { branch: 'snapshot_fallback', label: 'snapshot_fallback', context: `local fallback path${statusFragment}` };
   369|  }
   370|
   371|  if (deliveryBranch === 'auth_session_failure') {
   372|    return { branch: 'local_only', label: 'local_only', context: `auth/session unavailable${statusFragment}` };
   373|  }
   374|
   375|  return { branch: 'local_only', label: 'local_only', context: `unresolved branch${statusFragment}` };
   376|}
